gold.reference:
POINTS = {"AA": 10, "AB": 9, "BB": 8, "BC": 7, "CC": 6, "CD": 5, "DD": 4, "FF": 0}


def sgpa(courses):
    total = sum(c for _, c in courses)
    if not total:
        return 0.0
    return round(sum(POINTS[g.upper()] * c for g, c in courses) / total, 2)

def attendance_pct(attended, total):
    if total == 0:
        return 0.0
    return round(attended / total * 100, 1)

def library_fine(due, returned, reference=False):
    days = (returned - due).days
    if days <= 0:
        return 0
    fine = 2 * min(days, 7) + 5 * max(days - 7, 0)
    if reference:
        fine *= 2
    return min(fine, 100)

def find_clashes(slots):
    out = []
    for i in range(len(slots)):
        for j in range(i + 1, len(slots)):
            d1, s1, e1 = slots[i]
            d2, s2, e2 = slots[j]
            if d1 == d2 and s1 < e2 and s2 < e1:
                out.append((i, j))
    return out

def format_inr(amount):
    sign = "-" if amount < 0 else ""
    s = str(abs(amount))
    if len(s) <= 3:
        return sign + s
    head, tail = s[:-3], s[-3:]
    groups = []
    while len(head) > 2:
        groups.insert(0, head[-2:])
        head = head[:-2]
    if head:
        groups.insert(0, head)
    return sign + ",".join(groups + [tail])

