def class_average(marks):
    return sum(marks) / len(marks)

marks is a list of ints (0-100), or the string "AB" for an absent student. Absent students must be ignored
(not counted as 0). Return the average rounded to 2 decimals, or None if everyone was absent or the list is
empty.

gold.reference:
def class_average(marks):
    present = [m for m in marks if m != "AB"]
    if not present:
        return None
    return round(sum(present) / len(present), 2)

def balances(expenses, members):
    paid = {m: 0.0 for m in members}
    for payer, amount in expenses:
        if payer not in paid:
            raise ValueError(f"{payer} is not a member")
        paid[payer] += amount
    share = sum(paid.values()) / len(members) if members else 0.0
    return {m: round(p - share, 2) for m, p in paid.items()}

